package com.miaupy.business.api;
import com.miaupy.business.application.BusinessConfigurationUseCase;import com.miaupy.business.domain.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/business") public class BusinessConfigurationController{
 private final BusinessConfigurationUseCase useCase;public BusinessConfigurationController(BusinessConfigurationUseCase u){useCase=u;}
 @GetMapping("/settings")public SettingsResponse settings(){return SettingsResponse.from(useCase.getSettings());}@PutMapping("/settings")@PreAuthorize("hasAnyRole('OWNER','ADMIN')")public SettingsResponse settings(@Valid @RequestBody SettingsRequest r){return SettingsResponse.from(useCase.updateSettings(r.appointmentApprovalMode(),r.timezone(),r.currency(),r.allowOnlineBooking(),r.allowOnlineSales()));}
 @GetMapping("/address")public AddressResponse address(){return AddressResponse.from(useCase.getAddress());}@PutMapping("/address")@PreAuthorize("hasAnyRole('OWNER','ADMIN')")public AddressResponse address(@Valid @RequestBody AddressRequest r){return AddressResponse.from(useCase.updateAddress(r.street(),r.number(),r.district(),r.city(),r.state(),r.postalCode(),r.latitude(),r.longitude()));}
 public record SettingsRequest(@NotNull AppointmentApprovalMode appointmentApprovalMode,@NotBlank @Size(max=64)String timezone,@NotBlank @Pattern(regexp="[A-Z]{3}")String currency,boolean allowOnlineBooking,boolean allowOnlineSales){}public record SettingsResponse(AppointmentApprovalMode appointmentApprovalMode,String timezone,String currency,boolean allowOnlineBooking,boolean allowOnlineSales){static SettingsResponse from(BusinessSettings s){return new SettingsResponse(s.appointmentApprovalMode(),s.timezone(),s.currency(),s.allowOnlineBooking(),s.allowOnlineSales());}}
 public record AddressRequest(@NotBlank @Size(max=160)String street,@Size(max=30)String number,@Size(max=100)String district,@NotBlank @Size(max=100)String city,@NotBlank @Size(max=80)String state,@Size(max=20)String postalCode,@DecimalMin("-90")@DecimalMax("90")BigDecimal latitude,@DecimalMin("-180")@DecimalMax("180")BigDecimal longitude){}public record AddressResponse(String street,String number,String district,String city,String state,String postalCode,BigDecimal latitude,BigDecimal longitude){static AddressResponse from(BusinessAddress a){return new AddressResponse(a.street(),a.number(),a.district(),a.city(),a.state(),a.postalCode(),a.latitude(),a.longitude());}}}
